// 监控看板 - 账单核验列头筛选（支持按监控指标、指标状态筛选）
const MonitorVerifyFilterTh = ({
    metric,
    onMetricChange,
    status,
    onStatusChange,
    width,
    rowSpan,
}: {
    metric: string[];
    onMetricChange: (v: string[]) => void;
    status: string;
    onStatusChange: (v: string) => void;
    width?: string;
    rowSpan?: number;
}) => {
    const [openKind, setOpenKind] = useState<"metric" | "status" | null>(null);
    const wrapRef = React.useRef<HTMLDivElement>(null);
    const metricActive = metric.length > 0;
    const statusActive = status !== "";
    const toggleMetric = (value: string) => {
        onMetricChange(
            metric.includes(value)
                ? metric.filter((v) => v !== value)
                : [...metric, value]
        );
    };

    // 点击外部关闭下拉
    useEffect(() => {
        if (!openKind) return;
        const onDocClick = (e: MouseEvent) => {
            if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
                setOpenKind(null);
            }
        };
        document.addEventListener("mousedown", onDocClick);
        return () => document.removeEventListener("mousedown", onDocClick);
    }, [openKind]);

    return (
        <th rowSpan={rowSpan} style={width ? { minWidth: width } : undefined} className="px-3 py-3 text-left text-xs font-medium text-gray-600 align-bottom border-l border-gray-200">
            <div ref={wrapRef} className="inline-flex items-center gap-1">
                <span className="leading-[1.5]">账单核验</span>
                <div className="relative">
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            setOpenKind((v) => (v === "metric" ? null : "metric"));
                        }}
                        title="按监控指标筛选（可多选）"
                        className={`flex h-6 items-center justify-center gap-0.5 rounded px-1 transition-colors ${
                            metricActive ? "bg-blue-50 text-blue-600" : "text-gray-400 hover:bg-gray-100 hover:text-gray-600"
                        }`}
                    >
                        <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                        </svg>
                        <span className="text-[11px] leading-none">指标{metric.length > 0 ? `(${metric.length})` : ""}</span>
                    </button>
                    {openKind === "metric" && (
                        <div className="absolute top-full left-1/2 z-40 mt-1 w-[140px] -translate-x-1/2 rounded-lg border border-gray-200 bg-white py-1 shadow-lg">
                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onMetricChange([]);
                                    setOpenKind(null);
                                }}
                                className={`block w-full px-3 py-1.5 text-left text-[11px] leading-none ${
                                    metric.length === 0 ? "bg-blue-50 text-blue-600" : "text-gray-600 hover:bg-gray-50"
                                }`}
                            >
                                全部指标
                            </button>
                            <div className="my-1 border-t border-gray-100" />
                            {monitorVerifySubDefs.map((def) => {
                                const checked = metric.includes(def.name);
                                return (
                                    <button
                                        key={def.name}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            toggleMetric(def.name);
                                        }}
                                        className={`flex w-full items-center gap-1.5 px-3 py-1.5 text-left text-[11px] leading-none ${
                                            checked ? "bg-blue-50 text-blue-600" : "text-gray-600 hover:bg-gray-50"
                                        }`}
                                    >
                                        <span className={`flex h-3.5 w-3.5 flex-shrink-0 items-center justify-center rounded border ${checked ? "border-blue-600 bg-blue-600 text-white" : "border-gray-300"}`}>
                                            {checked && (
                                                <svg className="h-2.5 w-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                                                </svg>
                                            )}
                                        </span>
                                        <span>{def.name}</span>
                                    </button>
                                );
                            })}
                        </div>
                    )}
                </div>
                <div className="relative">
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            setOpenKind((v) => (v === "status" ? null : "status"));
                        }}
                        title="按指标状态筛选"
                        className={`flex h-6 items-center justify-center gap-0.5 rounded px-1 transition-colors ${
                            statusActive ? "bg-blue-50 text-blue-600" : "text-gray-400 hover:bg-gray-100 hover:text-gray-600"
                        }`}
                    >
                        <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                        </svg>
                        <span className="text-[11px] leading-none">状态</span>
                    </button>
                    {openKind === "status" && (
                        <div className="absolute top-full left-1/2 z-40 mt-1 w-[120px] -translate-x-1/2 rounded-lg border border-gray-200 bg-white py-1 shadow-lg">
                            {monitorVerifyStatusFilterOptions.map((opt) => (
                                <button
                                    key={opt.value}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onStatusChange(opt.value);
                                        setOpenKind(null);
                                    }}
                                    className={`block w-full px-3 py-1.5 text-left text-[11px] leading-none ${
                                        status === opt.value ? "bg-blue-50 text-blue-600" : "text-gray-600 hover:bg-gray-50"
                                    }`}
                                >
                                    {opt.label}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </th>
    );
};

// 监控看板 - 产品筛选下拉（多选，支持主产品/子产品；可一键清除）
const MonitorProductFilter = ({
    options,
    value,
    onChange,
}: {
    options: { id: number; name: string; isMain: boolean; parentId: number | null }[];
    value: number[];
    onChange: (v: number[]) => void;
}) => {
    const [open, setOpen] = useState(false);
    const wrapRef = React.useRef<HTMLDivElement>(null);

    // 点击外部关闭下拉
    useEffect(() => {
        if (!open) return;
        const onDocClick = (e: MouseEvent) => {
            if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
                setOpen(false);
            }
        };
        document.addEventListener("mousedown", onDocClick);
        return () => document.removeEventListener("mousedown", onDocClick);
    }, [open]);

    const toggle = (id: number) => {
        onChange(value.includes(id) ? value.filter((v) => v !== id) : [...value, id]);
    };

    return (
        <div ref={wrapRef} className="relative">
            <button
                onClick={() => setOpen((v) => !v)}
                className={`flex h-9 w-[240px] items-center justify-between gap-2 rounded-lg border bg-white px-3 text-sm transition-colors ${
                    value.length > 0 ? "border-blue-400 text-gray-900" : "border-gray-300 text-gray-600"
                } hover:border-blue-400`}
            >
                <span className="truncate">
                    {value.length === 0 ? "全部产品" : `已选 ${value.length} 个产品`}
                </span>
                <span className="flex flex-shrink-0 items-center gap-1">
                    {value.length > 0 && (
                        <span
                            onClick={(e) => {
                                e.stopPropagation();
                                onChange([]);
                            }}
                            className="text-gray-400 hover:text-gray-600"
                            aria-label="清除产品筛选"
                        >
                            <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </span>
                    )}
                    <svg className={`h-4 w-4 text-gray-400 transition-transform ${open ? "rotate-180" : ""}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                    </svg>
                </span>
            </button>
            {open && (
                <div className="absolute left-0 top-full z-40 mt-1 max-h-[320px] w-[320px] overflow-auto rounded-lg border border-gray-200 bg-white py-1 shadow-lg">
                    <button
                        onClick={() => onChange([])}
                        className={`block w-full px-3 py-1.5 text-left text-[12px] leading-none ${
                            value.length === 0 ? "bg-blue-50 text-blue-600" : "text-gray-600 hover:bg-gray-50"
                        }`}
                    >
                        全部产品
                    </button>
                    <div className="my-1 border-t border-gray-100" />
                    {options.map((opt) => {
                        const checked = value.includes(opt.id);
                        return (
                            <button
                                key={opt.id}
                                onClick={() => toggle(opt.id)}
                                className={`flex w-full items-center gap-1.5 px-3 py-1.5 text-left text-[12px] leading-none ${
                                    checked ? "bg-blue-50 text-blue-600" : "text-gray-600 hover:bg-gray-50"
                                }`}
                            >
                                <span className={`flex h-3.5 w-3.5 flex-shrink-0 items-center justify-center rounded border ${checked ? "border-blue-600 bg-blue-600 text-white" : "border-gray-300"}`}>
                                    {checked && (
                                        <svg className="h-2.5 w-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                                        </svg>
                                    )}
                                </span>
                                <span className="truncate">{cleanProductName(opt.name)}</span>
                            </button>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

// 监控看板 - 账期类型与选中值（用于生成各节点完成时间）
type MonitorBillType = "hour" | "day" | "month";

interface MonitorPeriodCtx {
    billType: MonitorBillType;
    period: string;      // month: YYYY-MM；day/hour: YYYY-MM-DD
    hour: number;        // hour 时使用，0~23
}

// 监控看板 - 生成各节点完成时间（随选中账期联动：月账单定位到月内某天，天账单定位到天内某时刻，小时账单定位到选中小时内的分钟秒）
const buildMonitorDoneTime = (ctx: MonitorPeriodCtx, day: number, time: string): string => {
    const [hh, mm, ss] = time.split(":");
    if (ctx.billType === "hour") {
        return `${ctx.period} ${pad2(ctx.hour)}:${mm}:${ss}`;
    }
    if (ctx.billType === "day") {
        return `${ctx.period} ${hh}:${mm}:${ss}`;
    }
    return `${ctx.period}-${pad2(day)} ${hh}:${mm}:${ss}`;
};

// 监控看板 - 是否有资源包抵扣（mock：按产品序号规律分布，部分产品无资源包，用于展示抵扣环节「不涉及」）
const monitorHasResourcePackage = (idx: number): boolean => idx % 3 !== 2;

// 监控看板 - 按序号生成各计费节点进度（主产品与子产品共用）
const buildMonitorNodes = (idx: number, ctx: MonitorPeriodCtx, hasPackage: boolean): Record<string, MonitorNodeState> => {
    // 计量上报：前 8 个完成，第 9、10 个进行中
    const meterDone = idx < 8;
    const meter: MonitorNodeState = meterDone
        ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 10, "08:00:00") }
        : { status: "running", progress: idx === 8 ? 72 : 45 };

    // 聚合：前 6 完成，6~8 进行中，第 9 未开始
    const dataAggregateDone = idx < 6;
    const dataAggregateRunning = idx >= 6 && idx < 9;
    const dataAggregate: MonitorNodeState = dataAggregateDone
        ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 11, "08:45:00") }
        : dataAggregateRunning
            ? { status: "running", progress: [68, 45, 22][idx - 6] }
            : { status: "pending", progress: 0 };

    // 出账：前 5 完成，5~8 进行中，第 9 未开始
    const productBillDone = idx < 5;
    const productBillRunning = idx >= 5 && idx < 9;
    const productBill: MonitorNodeState = productBillDone
        ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 11, "09:30:00") }
        : productBillRunning
            ? { status: "running", progress: [58, 80, 35, 62][idx - 5] }
            : { status: "pending", progress: 0 };

    // 结算分为抵扣、扣费两个环节：前 3 进行中，3~5 已完成，其余未开始；无资源包抵扣的产品，抵扣环节「不涉及」
    // 抵扣断点：有资源包抵扣的产品中，部分产品在某个时间的抵扣量为 0，抵扣环节标记为「异常（抵扣断点）」
    const settleRunning = idx < 3;
    const settleDone = idx >= 3 && idx < 6;
    const offsetBreak = hasPackage && (idx === 1 || idx === 4);
    const offset: MonitorNodeState = !hasPackage
        ? { status: "pending", progress: 0, na: true }
        : offsetBreak
            ? { status: "fail", progress: 100, failReason: "抵扣断点" }
            : settleRunning
                ? { status: "running", progress: [35, 52, 18][idx] }
                : settleDone
                    ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 13, "10:20:00") }
                    : { status: "pending", progress: 0 };
    const charge: MonitorNodeState = settleRunning
        ? { status: "running", progress: [24, 41, 13][idx] }
        : settleDone
            ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 13, "10:40:00") }
            : { status: "pending", progress: 0 };

    // 导出账单聚合 & 后台账单 - 平铺进度节点（不区分明细/详情，单条进度）
    const flatAggNode = (done: number, running: number, progresses: number[], day: number, time: string): MonitorNodeState => {
        if (idx < done) {
            return { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, day, time) };
        }
        const runningIdx = idx - done;
        if (runningIdx < running) {
            return { status: "running", progress: progresses[runningIdx] ?? 40 };
        }
        return { status: "pending", progress: 0 };
    };
    // 账单聚合：控制台(客户侧) 展示 小时/天/月账单
    // 每个账单列内包含「明细」「详情」两条子聚合进度，父节点状态由两条子进度汇总（明细、详情均完成才算完成）
    const aggNode = (
        detailCfg: { done: number; running: number; progresses: number[]; day: number; time: string },
        infoCfg: { done: number; running: number; progresses: number[]; day: number; time: string }
    ): MonitorNodeState => {
        const sub = (name: string, cfg: typeof detailCfg): MonitorAggSubNode => {
            if (idx < cfg.done) {
                return { name, status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, cfg.day, cfg.time) };
            }
            const runningIdx = idx - cfg.done;
            if (runningIdx < cfg.running) {
                return { name, status: "running", progress: cfg.progresses[runningIdx] ?? 40 };
            }
            return { name, status: "pending", progress: 0 };
        };
        const aggSubs = [sub("明细", detailCfg), sub("详情", infoCfg)];
        const status: MonitorNodeStatus = aggSubs.some((s) => s.status === "fail")
            ? "fail"
            : aggSubs.every((s) => s.status === "done")
                ? "done"
                : aggSubs.some((s) => s.status === "running")
                    ? "running"
                    : "pending";
        return {
            status,
            progress: Math.min(...aggSubs.map((s) => s.progress)),
            doneTime: status === "done" ? aggSubs[0].doneTime : undefined,
            aggSubs,
        };
    };

    // 控制台(客户侧)：小时账单 / 天账单 / 月账单
    const hourBillAgg = aggNode(
        { done: 5, running: 3, progresses: [82, 58, 30], day: 13, time: "11:20:00" },
        { done: 4, running: 3, progresses: [70, 46, 21], day: 13, time: "11:50:00" }
    );
    const dayBillAgg = aggNode(
        { done: 4, running: 3, progresses: [78, 55, 30], day: 13, time: "15:00:00" },
        { done: 3, running: 3, progresses: [66, 42, 18], day: 13, time: "15:40:00" }
    );
    const monthBillAgg = aggNode(
        { done: 3, running: 3, progresses: [65, 42, 18], day: 14, time: "10:30:00" },
        { done: 2, running: 3, progresses: [52, 33, 12], day: 14, time: "11:10:00" }
    );
    // 导出账单聚合：小时账单 / 天账单 / 月账单（不区分明细/详情，单条平铺进度）
    const exHourBillAgg = flatAggNode(5, 3, [80, 54, 28], 13, "12:10:00");
    const exDayBillAgg = flatAggNode(4, 3, [72, 48, 24], 14, "15:50:00");
    const exMonthBillAgg = flatAggNode(3, 3, [60, 38, 16], 15, "10:50:00");
    // 后台账单(含经营分析收入)：小时账单 / 天账单 / 月账单（不区分明细/详情，单条平铺进度）
    const bgHourBillAgg = flatAggNode(4, 3, [74, 50, 26], 13, "12:40:00");
    const bgDayBillAgg = flatAggNode(3, 3, [68, 45, 20], 14, "16:30:00");
    const bgMonthBillAgg = flatAggNode(2, 3, [58, 36, 14], 15, "11:40:00");

    // 成本聚合：前 3 完成，3~5 进行中，5~7 未开始，其余未开始
    const costAggDone = idx < 3;
    const costAggRunning = idx >= 3 && idx < 5;
    const costAgg: MonitorNodeState = costAggDone
        ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 15, "14:30:00") }
        : costAggRunning
            ? { status: "running", progress: [45, 20][idx - 3] }
            : { status: "pending", progress: 0 };

    // 成本生产：前 2 完成，2~4 进行中，4~6 未开始，其余未开始
    const costProdDone = idx < 2;
    const costProdRunning = idx >= 2 && idx < 4;
    const costProd: MonitorNodeState = costProdDone
        ? { status: "done", progress: 100, doneTime: buildMonitorDoneTime(ctx, 15, "15:00:00") }
        : costProdRunning
            ? { status: "running", progress: [65, 35][idx - 2] }
            : { status: "pending", progress: 0 };

    // 账单核验：各核验字段子节点；按产品/字段序号规律分配 验证通过/告警/异常 三种核验状态
    const verifySubs: MonitorVerifySubNode[] = monitorVerifySubDefs.map((def, si) => ({
        name: def.name,
        detail: def.detail,
        status: ((idx + si) % 4 === 1 ? "warn" : (idx + si) % 4 === 2 ? "fail" : "pass") as MonitorVerifyStatus,
    }));
    const verify: MonitorNodeState = { status: "pending", progress: 0, verifySubs };

    return {
        meter,
        dataAggregate,
        productBill,
        offset,
        charge,
        // 控制台(客户侧)账单聚合
        hourBillAgg,
        dayBillAgg,
        monthBillAgg,
        // 导出账单聚合
        exHourBillAgg,
        exDayBillAgg,
        exMonthBillAgg,
        // 后台账单(含经营分析收入)
        bgHourBillAgg,
        bgDayBillAgg,
        bgMonthBillAgg,
        costAgg,
        costProd,
        verify,
    };
};

// 监控看板 - 主产品下的子产品名称（mock：仅部分产品为主产品，其余为独立产品）
const monitorSubProductNames: Record<number, string[]> = {
    1: ["云服务器 ECS_裸金属CPU(计量)", "云服务器 ECS_裸金属GPU(计量)", "云服务器 ECS_通用型(计量)"],
    2: ["托管集群服务 MCS_容器服务", "托管集群服务 MCS_A机器"],
    5: ["对象存储 OSS_标准存储(计量)", "对象存储 OSS_低频存储(计量)"],
    7: ["内容分发 CDN_流量(计量)", "内容分发 CDN_带宽(计量)"],
};

// 监控看板 - 平台各产品在各计费节点的进度（数据口径与「产品分析」一致）
// 出账周期 mock：按产品规律分配 小时/天/月/多出账周期，便于展示列表效果。
// 多出账周期直接以数组表达，如 ["hour","day"]（小时、天）、["hour","month"]（小时、月）
const monitorBillingCycleOf = (idx: number): MonitorBillingCycle =>
    ([
        ["hour", "day"], ["month"], ["hour"], ["hour", "month"], ["month"],
        ["day"], ["hour"], ["day"], ["month"], ["hour", "day"],
    ] as MonitorBillingCycle[])[idx % 10];

// 出账周期 - 中文展示（多出账周期按「、」连接，如 小时、天 / 小时、月）
const formatBillingCycle = (cycles: MonitorBillingCycle): string => {
    const labelMap: Record<"hour" | "day" | "month", string> = { hour: "小时", day: "天", month: "月" };
    if (cycles.length === 0) return "-";
    return cycles.map((c) => labelMap[c]).join("、");
};

const buildMonitorProductRows = (ctx: MonitorPeriodCtx): MonitorProductRow[] => {
    const rows: MonitorProductRow[] = [];
    // mock 成本数据：将 productCost 按约 4:6 拆分为成本聚合与成本生产
    const splitCost = (total: number): [number, number] => {
        const agg = Math.round(total * 0.4);
        return [agg, total - agg];
    };
    productAnalysisData.forEach((p, idx) => {
        const subNames = monitorSubProductNames[p.id] ?? [];
        const [agg, prod] = splitCost(p.productCost);
        // 主产品作为独立行
        rows.push({
            id: p.id,
            productName: p.productName,
            productLine: p.productLine,
            settlementUnit: p.settlementUnit,
            billingCycle: monitorBillingCycleOf(idx),
            isMain: subNames.length > 0,
            parentId: null,
            subCount: subNames.length,
            hasPackage: monitorHasResourcePackage(idx),
            costAgg: agg,
            costProd: prod,
            nodes: buildMonitorNodes(idx, ctx, monitorHasResourcePackage(idx)),
        });
        // 子产品同样作为独立行（子产品也是一个个单独的产品，直接出现在列表中）
        subNames.forEach((name, si) => {
            const subIdx = (idx + si + 1) % 10;
            const [subAgg, subProd] = splitCost(p.productCost * 0.25);
            rows.push({
                id: p.id * 100 + si + 1,
                productName: name,
                productLine: p.productLine,
                settlementUnit: p.settlementUnit,
                billingCycle: monitorBillingCycleOf(subIdx),
                isMain: false,
                parentId: p.id,
                subCount: 0,
                hasPackage: monitorHasResourcePackage(subIdx),
                costAgg: subAgg,
                costProd: subProd,
                nodes: buildMonitorNodes(subIdx, ctx, monitorHasResourcePackage(subIdx)),
            });
        });
    });
    return rows;
};

const getDeptRevenueDetailRows = (unit: DepartmentAnalysisRow, period: string): DeptRevenueDetailRow[] => {
    const products = deptProductRevenueMap[unit.opsUnit];
    if (!products || products.length === 0) return [];
    return products.map((p) => ({
        period: period.replace("-", ""),
        revenueSource: "账单",
        sourceName: p.productName,
        amount: p.amount,
    }));
};

// 产品分析 - 总收入明细（收入明细 Tab）数据：按「收入类型/收入来源」拆分，金额之和等于总收入
const productRevenueDetailTypes: { type: string; source: string }[] = [
    { type: "自身账单", source: "账单" },
];

const getProductRevenueDetailRows = (row: ProductAnalysisRow) => {
    const total = row.totalRevenue;
    if (total === 0) return [];
    const types = productRevenueDetailTypes;
    const weights = types.map((_, i) => types.length - i);
    const weightSum = weights.reduce((s, w) => s + w, 0);
    let allocated = 0;
    return types.map((t, i) => {
        const amount = i === types.length - 1
            ? total - allocated
            : Math.round((total * weights[i]) / weightSum * 100) / 100;
        allocated += amount;
        return { period: row.period, type: t.type, source: t.source, amount };
    });
};

// 产品分析 - 通用结算单元账单金额明细：每个结算单元都可能关联外部portal账号，
// 因此列表结构与「企业内收入」明细一致：来源一结算单元账单 + 来源二外部portal账号。
const outerGroupSettlementUnits = ["智汇云-云平台部", "智汇云-智能工程部", "智汇云-系统部"];
const getUnitBillDetailRows = (row: ProductAnalysisRow, amount: number, title?: string) => {
    const rows: { period: string; unitName: string; source: string; amount: number; type: "internal" | "portal" }[] = [];
    if (amount === 0) return rows;

    // 本结算单元收入：弹框只展示当前产品归属的结算单元，仅一条结算单元收入记录
    if (title === "本结算单元收入") {
        rows.push({ period: row.period, unitName: row.settlementUnit, source: row.settlementUnit, amount, type: "internal" });
        return rows;
    }

    // 来源一：集团内部结算单元账单
    const billTotal = row.hasOuterPortal ? Math.round(amount * 0.8 * 100) / 100 : amount;
    const units = outerGroupSettlementUnits;
    const weights = units.map((_, i) => units.length - i);
    const weightSum = weights.reduce((s, w) => s + w, 0);
    let allocated = 0;
    units.forEach((unitName, i) => {
        const amt = i === units.length - 1
            ? billTotal - allocated
            : Math.round((billTotal * weights[i]) / weightSum * 100) / 100;
        allocated += amt;
        rows.push({ period: row.period, unitName, source: unitName, amount: amt, type: "internal" });
    });

    // 来源二：内部结算单元账号在外部portal上使用产生的费用（关联回内部结算单元）
    if (row.hasOuterPortal) {
        const portalTotal = Math.round(amount * 0.2 * 100) / 100;
        const accounts = innerRevenuePortalUsageAccounts;
        const accountWeights = accounts.map((_, i) => accounts.length - i);
        const accountWeightSum = accountWeights.reduce((s, w) => s + w, 0);
        let portalAllocated = 0;
        accounts.forEach((account, i) => {
            const amt = i === accounts.length - 1
                ? portalTotal - portalAllocated
                : Math.round((portalTotal * accountWeights[i]) / accountWeightSum * 100) / 100;
            portalAllocated += amt;
            const [unitName, portalAccount] = account.split("@");
            rows.push({ period: row.period, unitName, source: portalAccount, amount: amt, type: "portal" });
        });
    }

    return rows;
};



// 产品分析 - 外部Portal账号（名称）
const outerPortalTenants = [
    { name: "张三" },
    { name: "李四" },
];

// 产品分析 - 「企业外收入」明细：拆分「收入来源」与「来源名称」两列，
// 合并「集团下外部结算单元账单」与「外部Portal名称(域名)」两类收入来源
const getOuterRevenueDetailRows = (row: ProductAnalysisRow) => {
    const rows: { period: string; unitName: string; source: string; sourceName: string; amount: number }[] = [];

    // 来源一：集团下外部结算单元账单（按结算单元拆分）
    const groupTotal = row.outerGroupRevenue;
    if (groupTotal > 0) {
        const units = outerGroupSettlementUnits;
        const weights = units.map((_, i) => units.length - i);
        const weightSum = weights.reduce((s, w) => s + w, 0);
        let allocated = 0;
        units.forEach((unitName, i) => {
            const amount = i === units.length - 1
                ? groupTotal - allocated
                : Math.round((groupTotal * weights[i]) / weightSum * 100) / 100;
            allocated += amount;
            rows.push({ period: row.period, unitName, source: "集团下外部结算单元账单", sourceName: unitName, amount });
        });
    }

    // 来源二：外部Portal名称(域名)（按租户名称/域名拆分）
    const portalTotal = row.outerPortalRevenue;
    if (portalTotal > 0) {
        const tenants = outerPortalTenants;
        const weights = tenants.map((_, i) => tenants.length - i);
        const weightSum = weights.reduce((s, w) => s + w, 0);
        let allocated = 0;
        tenants.forEach((t, i) => {
            const amount = i === tenants.length - 1
                ? portalTotal - allocated
                : Math.round((portalTotal * weights[i]) / weightSum * 100) / 100;
            allocated += amount;
            rows.push({ period: row.period, unitName: "-", source: "外部Portal名称(域名)", sourceName: t.name, amount });
        });
    }

    return rows;
};

// 产品分析 - 「企业内收入」明细：来源一为集团内部结算单元账单，来源二为内部结算单元账号在外部portal上
// 使用产生的费用（该费用关联回内部结算单元，计入内部收入）。仅当 hasOuterPortal 为 true 时才存在来源二。
const innerRevenuePortalUsageAccounts = ["智汇云-云平台部@外部portal账号A", "智汇云-智能工程部@外部portal账号B"];

// 来源一：集团内部结算单元账单明细
const getInnerRevenueUnitBillRows = (row: ProductAnalysisRow) => {
    const total = row.hasOuterPortal ? Math.round(row.innerRevenue * 0.8 * 100) / 100 : row.innerRevenue;
    if (total === 0) return [];
    const units = outerGroupSettlementUnits;
    const weights = units.map((_, i) => units.length - i);
    const weightSum = weights.reduce((s, w) => s + w, 0);
    let allocated = 0;
    return units.map((unitName, i) => {
        const amount = i === units.length - 1
            ? total - allocated
            : Math.round((total * weights[i]) / weightSum * 100) / 100;
        allocated += amount;
        return { period: row.period, unitName, amount };
    });
};

// 来源二：内部结算单元账号在外部portal上使用产生的费用明细（关联回内部结算单元，计入内部收入）
const getInnerRevenuePortalUsageRows = (row: ProductAnalysisRow) => {
    if (!row.hasOuterPortal) return [];
    const total = Math.round(row.innerRevenue * 0.2 * 100) / 100;
    if (total === 0) return [];
    const accounts = innerRevenuePortalUsageAccounts;
    const weights = accounts.map((_, i) => accounts.length - i);
    const weightSum = weights.reduce((s, w) => s + w, 0);
    let allocated = 0;
    return accounts.map((account, i) => {
        const amount = i === accounts.length - 1
            ? total - allocated
            : Math.round((total * weights[i]) / weightSum * 100) / 100;
        allocated += amount;
        const [unitName, portalAccount] = account.split("@");
        return { period: row.period, unitName, portalAccount, amount };
    });
};

// 产品分析 - 「企业内收入」明细：将「集团内部结算单元账单」与「内部结算单元账号在外部portal使用费用」
// 合并为一张表展示。收入来源列取值：内部结算单元名称（来源一）或 外部Portal账号（来源二）
const getInnerRevenueMergedRows = (row: ProductAnalysisRow) => {
    const rows: { period: string; unitName: string; source: string; amount: number; type: "internal" | "portal" }[] = [];
    getInnerRevenueUnitBillRows(row).forEach((r) => {
        rows.push({ period: r.period, unitName: r.unitName, source: r.unitName, amount: r.amount, type: "internal" });
    });
    getInnerRevenuePortalUsageRows(row).forEach((r) => {
        rows.push({ period: r.period, unitName: r.unitName, source: r.portalAccount, amount: r.amount, type: "portal" });
    });
    return rows;
};

// ===== 经营分析 - 整体分析 =====

// 结算单元 → 经营属性映射（与「内部折扣设置」initialUnitDiscounts 保持一致，此处提前定义供整体分析模块使用）
const UNIT_DEPT_ATTR_MAP: Record<string, 'inner' | 'biz' | ''> = {
    '智汇云-应用平台部': 'inner',
    '智汇云-商业化产品部': 'inner',
    '智汇云-云平台部': 'inner',
    '智汇云-系统运维部': 'inner',
    '智汇云-基础架构部': 'biz',
    '智汇云-安全技术部': 'biz',
    '智汇云-系统部': 'biz',
    '智汇云-数据平台部': 'biz',
    '360人工智能研究院': 'biz',
    '智汇云-交付服务部': 'biz',
    '智汇云-智能工程部': 'biz',
    '智汇云-研发效能部': '',
};

// 根据结算单元名称匹配经营属性（前缀匹配 UNIT_DEPT_ATTR_MAP 的 key）
const getUnitDeptAttr = (settlementUnit: string): 'inner' | 'biz' | '' => {
    const keys = Object.keys(UNIT_DEPT_ATTR_MAP).sort((a, b) => b.length - a.length); // 长 key 优先匹配
    const matched = keys.find((k) => settlementUnit.startsWith(k));
    if (matched) return UNIT_DEPT_ATTR_MAP[matched];
    return ''; // 未配置的结算单元默认为空，后续按业务需要处理
};

// 整体分析行：字段与「产品分析」保持一致，数值为平台侧全部产品的合计值
interface OverallAnalysisRow {
    id: number;
    period: string;                 // 账期（按月/天/小时）
    totalRevenue: number;           // 总收入(元)
    innerRevenue: number;           // 企业内收入(元)
    innerSettleRevenue: number;     // 内结收入(元)：标记为内部企业的账号中，经营属性为「内结」的结算单元账单金额
    innerBizRevenue: number;        // 经营收入(元)：标记为内部企业的账号中，经营属性为「经营」的结算单元账单金额
    innerNonZyunRevenue: number;    // 企业内非智汇云收入(元)
    zyunNonUnitRevenue: number;     // 智汇云内非本结算单元收入(元)
    unitRevenue: number;            // 本结算单元收入(元)
    outerRevenue: number;           // 企业外收入(元)
    outerInnerPriceRevenue: number; // 外部收入对应的内结算价收入(元)
    innerTotalRevenue: number;      // 内结算总收入(元)
    productCost: number;            // 产品成本(元)
    innerCost: number;              // 内部成本(元)：所有结算单元下资源组消费的账单金额总和
    outerCost: number;              // 外部成本(元)：所有产品的外部收入
    innerProfit: number;            // 内结算价利润(元)
    outerProfit: number;            // 外部利润(元)
    innerMargin: number;            // 内结算毛利率
    outerMargin: number;            // 外部毛利率
    balance: number;                // 收支差额(元)
}

// 整体分析 - 产品分析各列求和（作为单账期的基准值）
const overallBaseTotals = productAnalysisData.reduce(
    (acc, row) => {
        const attr = getUnitDeptAttr(row.settlementUnit);
        return {
            totalRevenue: acc.totalRevenue + row.totalRevenue,
            innerRevenue: acc.innerRevenue + row.innerRevenue,
            innerSettleRevenue: acc.innerSettleRevenue + (attr === 'inner' ? row.innerRevenue : 0),
            innerBizRevenue: acc.innerBizRevenue + (attr === 'biz' ? row.innerRevenue : 0),
            innerNonZyunRevenue: acc.innerNonZyunRevenue + row.innerNonZyunRevenue,
            zyunNonUnitRevenue: acc.zyunNonUnitRevenue + row.zyunNonUnitRevenue,
            unitRevenue: acc.unitRevenue + row.unitRevenue,
            outerRevenue: acc.outerRevenue + row.outerRevenue,
            outerInnerPriceRevenue: acc.outerInnerPriceRevenue + row.outerInnerPriceRevenue,
            innerTotalRevenue: acc.innerTotalRevenue + row.innerTotalRevenue,
            productCost: acc.productCost + row.productCost,
            innerProfit: acc.innerProfit + row.innerProfit,
            outerProfit: acc.outerProfit + row.outerProfit,
            balance: acc.balance + row.balance,
        };
    },
    {
        totalRevenue: 0, innerRevenue: 0, innerSettleRevenue: 0, innerBizRevenue: 0,
        innerNonZyunRevenue: 0,
        zyunNonUnitRevenue: 0, unitRevenue: 0, outerRevenue: 0, outerInnerPriceRevenue: 0,
        innerTotalRevenue: 0, productCost: 0, innerProfit: 0, outerProfit: 0, balance: 0,
    }
);

// 整体分析 - 稳定的伪随机波动系数（保证每次渲染结果一致）
const overallWave = (seed: number) => {
    const s = Math.sin(seed * 12.9898) * 43758.5453;
    return s - Math.floor(s); // 0 ~ 1
};

// 整体分析 - 按账期与缩放比例构造一行合计数据
const buildOverallRow = (id: number, period: string, scale: number, seed: number): OverallAnalysisRow => {
    const revFactor = scale * (0.88 + overallWave(seed) * 0.26);       // 收入波动
    const costFactor = scale * (0.9 + overallWave(seed + 77) * 0.22);  // 成本波动
    const b = overallBaseTotals;

    const totalRevenue = b.totalRevenue * revFactor;
    const innerRevenue = b.innerRevenue * revFactor;
    const innerSettleRevenue = b.innerSettleRevenue * revFactor;
    const innerBizRevenue = b.innerBizRevenue * revFactor;
    const outerRevenue = b.outerRevenue * revFactor;
    const outerInnerPriceRevenue = b.outerInnerPriceRevenue * revFactor;
    const innerTotalRevenue = b.innerTotalRevenue * revFactor;
    const productCost = b.productCost * costFactor;
    const outerCost = outerRevenue;             // 外部成本(元) = 所有产品的外部收入
    const innerCost = productCost - outerCost;  // 内部成本(元) = 总成本 - 外部成本
    const innerProfit = innerTotalRevenue - productCost;
    const outerProfit = outerRevenue - outerInnerPriceRevenue;

    return {
        id,
        period,
        totalRevenue,
        innerRevenue,
        innerSettleRevenue,
        innerBizRevenue,
        innerNonZyunRevenue: b.innerNonZyunRevenue * revFactor,
        zyunNonUnitRevenue: b.zyunNonUnitRevenue * revFactor,
        unitRevenue: b.unitRevenue * revFactor,
        outerRevenue,
        outerInnerPriceRevenue,
        innerTotalRevenue,
        productCost,
        innerCost,
        outerCost,
        innerProfit,
        outerProfit,
        innerMargin: innerTotalRevenue === 0 ? 0 : (innerProfit / innerTotalRevenue) * 100,
        outerMargin: outerRevenue === 0 ? 0 : (outerProfit / outerRevenue) * 100,
        balance: innerProfit + outerProfit,
    };
};

// 整体分析 - 两位数补零
const pad2 = (n: number) => String(n).padStart(2, "0");

// 整体分析 - 月账单序列：选中月及其前 5 个月（共 6 个月，按时间正序）
const buildOverallMonthlySeries = (anchorMonth: string): OverallAnalysisRow[] => {
    const [y, m] = anchorMonth.split("-").map(Number);
    if (!y || !m) return [];
    return Array.from({ length: 6 }, (_, idx) => {
        const d = new Date(y, m - 1 - (5 - idx), 1);
        const yy = d.getFullYear();
        const mm = d.getMonth() + 1;
        return buildOverallRow(idx + 1, `${yy}${pad2(mm)}`, 1, yy * 12 + mm);
    });
};

// 整体分析 - 天账单序列：选中天及其前 29 天（共 30 天，按时间正序）
const buildOverallDailySeries = (anchorDate: string): OverallAnalysisRow[] => {
    const [y, m, d] = anchorDate.split("-").map(Number);
    if (!y || !m || !d) return [];
    return Array.from({ length: 30 }, (_, idx) => {
        const cur = new Date(y, m - 1, d - (29 - idx));
        const yy = cur.getFullYear();
        const mm = cur.getMonth() + 1;
        const dd = cur.getDate();
        return buildOverallRow(idx + 1, `${yy}${pad2(mm)}${pad2(dd)}`, 1 / 31, yy * 372 + mm * 31 + dd);
    });
};

// 整体分析 - 小时账单序列：选中天的选中小时及其前 23 个小时（按时间正序，末条为选中小时）
const buildOverallHourlySeries = (anchorDate: string, anchorHour = 23): OverallAnalysisRow[] => {
    const [y, m, d] = anchorDate.split("-").map(Number);
    if (!y || !m || !d) return [];
    const rows: OverallAnalysisRow[] = [];
    for (let back = 23; back >= 0; back--) {
        const cur = new Date(y, m - 1, d, anchorHour - back);
        const yy = cur.getFullYear();
        const mm = cur.getMonth() + 1;
        const dd = cur.getDate();
        const hh = cur.getHours();
        rows.push(
            buildOverallRow(
                rows.length + 1,
                `${yy}${pad2(mm)}${pad2(dd)} ${pad2(hh)}:00`,
                1 / (31 * 24),
                yy * 8928 + mm * 744 + dd * 24 + hh
            )
        );
    }
    return rows;
};

// 整体分析 - 报表：根据账单类型与账期取数据源（末条为选中账期，倒数第二条用于环比）
const getOverallDataset = (billType: string, period: string, hour = 23) => {
    if (billType === "day") return buildOverallDailySeries(period);
    if (billType === "hour") return buildOverallHourlySeries(period, hour);
    return buildOverallMonthlySeries(period);
};

// ===== 整体分析 - 趋势：时间区间数据源 =====

// 趋势区间上限：月趋势最多 6 个月、日趋势最多 31 天、小时趋势最多 7 天（按天计）
const OVERALL_TREND_LIMIT = { month: 6, day: 31, hour: 7 } as const;

// 日期字符串（YYYY-MM-DD）与 Date 互转
const parseDay = (s: string) => {
    const [y, m, d] = s.split("-").map(Number);
    return y && m && d ? new Date(y, m - 1, d) : null;
};
const formatDay = (d: Date) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
const addDays = (s: string, n: number) => {
    const d = parseDay(s);
    if (!d) return s;
    d.setDate(d.getDate() + n);
    return formatDay(d);
};
// 含首尾的天数差
const diffDays = (start: string, end: string) => {
    const a = parseDay(start);
    const b = parseDay(end);
    if (!a || !b) return 0;
    return Math.round((b.getTime() - a.getTime()) / 86400000) + 1;
};

// 月字符串（YYYY-MM）工具
const monthIndex = (s: string) => {
    const [y, m] = s.split("-").map(Number);
    return y && m ? y * 12 + (m - 1) : NaN;
};
const formatMonth = (idx: number) => `${Math.floor(idx / 12)}-${pad2((idx % 12) + 1)}`;
const addMonths = (s: string, n: number) => {
    const idx = monthIndex(s);
    return Number.isNaN(idx) ? s : formatMonth(idx + n);
};
// 含首尾的月份数差
const diffMonths = (start: string, end: string) => {
    const a = monthIndex(start);
    const b = monthIndex(end);
    return Number.isNaN(a) || Number.isNaN(b) ? 0 : b - a + 1;
};

// 趋势 - 月区间序列（按时间正序）
const buildOverallMonthRange = (start: string, end: string): OverallAnalysisRow[] => {
    const total = diffMonths(start, end);
    if (total <= 0) return [];
    return Array.from({ length: Math.min(total, OVERALL_TREND_LIMIT.month) }, (_, idx) => {
        const cur = formatMonth(monthIndex(start) + idx);
        const [yy, mm] = cur.split("-").map(Number);
        return buildOverallRow(idx + 1, `${yy}${pad2(mm)}`, 1, yy * 12 + mm);
    });
};

// 趋势 - 日区间序列（按时间正序）
const buildOverallDayRange = (start: string, end: string): OverallAnalysisRow[] => {
    const total = diffDays(start, end);
    if (total <= 0) return [];
    return Array.from({ length: Math.min(total, OVERALL_TREND_LIMIT.day) }, (_, idx) => {
        const cur = parseDay(addDays(start, idx))!;
        const yy = cur.getFullYear();
        const mm = cur.getMonth() + 1;
        const dd = cur.getDate();
        return buildOverallRow(idx + 1, `${yy}${pad2(mm)}${pad2(dd)}`, 1 / 31, yy * 372 + mm * 31 + dd);
    });
};

// 趋势 - 小时区间序列（区间内每天 24 个点，按时间正序）
const buildOverallHourRange = (start: string, end: string): OverallAnalysisRow[] => {
    const total = diffDays(start, end);
    if (total <= 0) return [];
    const days = Math.min(total, OVERALL_TREND_LIMIT.hour);
    const rows: OverallAnalysisRow[] = [];
    for (let i = 0; i < days; i++) {
        const cur = parseDay(addDays(start, i))!;
        const yy = cur.getFullYear();
        const mm = cur.getMonth() + 1;
        const dd = cur.getDate();
        for (let h = 0; h < 24; h++) {
            rows.push(
                buildOverallRow(
                    rows.length + 1,
                    `${yy}${pad2(mm)}${pad2(dd)} ${pad2(h)}:00`,
                    1 / (31 * 24),
                    yy * 8928 + mm * 744 + dd * 24 + h
                )
            );
        }
    }
    return rows;
};

// 趋势 - 根据账单类型与区间取数据源
const getOverallTrendDataset = (billType: string, start: string, end: string) => {
    if (billType === "day") return buildOverallDayRange(start, end);
    if (billType === "hour") return buildOverallHourRange(start, end);
    return buildOverallMonthRange(start, end);
};

// 整体分析 - 账期短标签（图表 X 轴展示）
const overallShortLabel = (period: string, billType: string) => {
    if (billType === "hour") {
        const [datePart, timePart] = period.split(" ");
        return `${Number(datePart.slice(6, 8))}日${(timePart ?? "").slice(0, 2)}时`;
    }
    if (billType === "day") return `${Number(period.slice(4, 6))}/${Number(period.slice(6, 8))}`;
    return `${Number(period.slice(0, 4))}/${Number(period.slice(4, 6))}`;
};

// ===== 产品分析 - 单列趋势（抽屉「趋势」Tab 数据源与图表） =====

// 产品分析 - 单列趋势数据点
interface ProductColumnTrendPoint {
    period: string; // 账期标签（月/天/小时）
    value: number;  // 该账期该列收入(元)
}

// 产品分析 - 稳定伪随机波动（保证同一产品、同一账期结果一致）
const productColumnWave = (seed: number) => {
    const s = Math.sin(seed * 12.9898) * 43758.5453;
    return s - Math.floor(s);
};

// 产品分析 - 根据账单类型、选中时间与基准值构造「选中时间前 N 期」趋势序列（末条=选中时间）
const buildProductColumnTrend = (
    billType: string,
    anchor: { month: string; date: string; hour: number },
    baseValue: number,
    seedBase: number,
): ProductColumnTrendPoint[] => {
    const make = (period: string, seed: number, idx: number, total: number): ProductColumnTrendPoint => ({
        period,
        // 末条为选中账期，值等于基准值；历史账期叠加稳定波动
        value: Math.round(baseValue * (idx === total - 1 ? 1 : 0.72 + productColumnWave(seed) * 0.56) * 100) / 100,
    });

    if (billType === "day") {
        if (!parseDay(anchor.date)) return [];
        return Array.from({ length: 31 }, (_, idx) => {
            const cur = parseDay(addDays(anchor.date, idx - 30))!;
            const yy = cur.getFullYear();
            const mm = cur.getMonth() + 1;
            const dd = cur.getDate();
            return make(`${yy}${pad2(mm)}${pad2(dd)}`, seedBase + yy * 372 + mm * 31 + dd, idx, 31);
        });
    }

    if (billType === "hour") {
        if (!parseDay(anchor.date)) return [];
        const total = 7 * 24;
        const rows: ProductColumnTrendPoint[] = [];
        const d = parseDay(anchor.date)!;
        for (let back = total - 1; back >= 0; back--) {
            const cur = new Date(d.getFullYear(), d.getMonth(), d.getDate(), anchor.hour - back);
            const yy = cur.getFullYear();
            const mm = cur.getMonth() + 1;
            const dd = cur.getDate();
            const hh = cur.getHours();
            rows.push(
                make(`${yy}${pad2(mm)}${pad2(dd)} ${pad2(hh)}:00`, seedBase + yy * 8928 + mm * 744 + dd * 24 + hh, rows.length, total)
            );
        }
        return rows;
    }

    const anchorIdx = monthIndex(anchor.month);
    if (Number.isNaN(anchorIdx)) return [];
    return Array.from({ length: 6 }, (_, idx) => {
        const cur = formatMonth(anchorIdx - 5 + idx);
        const [yy, mm] = cur.split("-").map(Number);
        return make(`${yy}${pad2(mm)}`, seedBase + yy * 12 + mm, idx, 6);
    });
};

// 产品分析 - 单列趋势曲线图（纯 SVG 实现，单系列）
const ProductColumnTrendChart = ({
    points,
    billType,
}: {
    points: ProductColumnTrendPoint[];
    billType: string;
}) => {
    const [activeIndex, setActiveIndex] = useState<number | null>(null);

    const W = 900;
    const H = 300;
    const padL = 86;
    const padR = 24;
    const padT = 20;
    const padB = 44;
    const innerW = W - padL - padR;
    const innerH = H - padT - padB;

    if (points.length === 0) {
        return <div className="flex h-[300px] items-center justify-center text-sm text-gray-400">暂无趋势数据</div>;
    }

    const values = points.map((p) => p.value);
    const maxVal = Math.max(...values, 1);
    const step = Math.pow(10, Math.floor(Math.log10(maxVal))) / 2;
    const yMax = Math.ceil(maxVal / step) * step;

    const xAt = (i: number) => (points.length === 1 ? padL + innerW / 2 : padL + (innerW * i) / (points.length - 1));
    const yAt = (v: number) => padT + innerH - (v / yMax) * innerH;
    const toPolyline = () => values.map((v, i) => `${xAt(i)},${yAt(v)}`).join(" ");
    const toAreaPath = () =>
        `M ${xAt(0)},${padT + innerH} ` + values.map((v, i) => `L ${xAt(i)},${yAt(v)}`).join(" ") + ` L ${xAt(values.length - 1)},${padT + innerH} Z`;

    const tickCount = 5;
    const ticks = Array.from({ length: tickCount + 1 }, (_, i) => i);
    const labelStride = Math.max(1, Math.ceil(points.length / 12));
    const showDots = points.length <= 40;

    return (
        <div className="relative">
            <svg viewBox={`0 0 ${W} ${H}`} className="w-full" style={{ height: 300 }} preserveAspectRatio="none">
                <defs>
                    <linearGradient id="productColTrendFill" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#0f73f6" stopOpacity="0.16" />
                        <stop offset="100%" stopColor="#0f73f6" stopOpacity="0" />
                    </linearGradient>
                </defs>

                {ticks.map((t) => {
                    const y = padT + innerH - (innerH * t) / tickCount;
                    return (
                        <g key={`tick-${t}`}>
                            <line x1={padL} y1={y} x2={W - padR} y2={y} stroke="#eef0f3" strokeWidth={1} />
                            <text x={padL - 10} y={y + 4} textAnchor="end" className="fill-gray-400" style={{ fontSize: 11 }}>
                                {((yMax / tickCount) * t / 10000).toFixed(0)} 万
                            </text>
                        </g>
                    );
                })}

                <path d={toAreaPath()} fill="url(#productColTrendFill)" />
                <polyline points={toPolyline()} fill="none" stroke="#0f73f6" strokeWidth={2} strokeLinejoin="round" strokeLinecap="round" />

                {points.map((p, i) =>
                    showDots || activeIndex === i ? (
                        <circle key={`pt-${i}`} cx={xAt(i)} cy={yAt(p.value)} r={activeIndex === i ? 4.5 : 2.5} fill="#fff" stroke="#0f73f6" strokeWidth={2} />
                    ) : null
                )}

                {points.map((p, i) =>
                    i % labelStride === 0 ? (
                        <text key={`lb-${i}`} x={xAt(i)} y={H - padB + 20} textAnchor="middle" className="fill-gray-400" style={{ fontSize: 11 }}>
                            {overallShortLabel(p.period, billType)}
                        </text>
                    ) : null
                )}

                {activeIndex !== null && (
                    <line x1={xAt(activeIndex)} y1={padT} x2={xAt(activeIndex)} y2={padT + innerH} stroke="#c9d3e0" strokeWidth={1} strokeDasharray="4 3" />
                )}

                {points.map((_, i) => {
                    const bandW = innerW / Math.max(points.length - 1, 1);
                    return (
                        <rect
                            key={`hit-${i}`}
                            x={xAt(i) - bandW / 2}
                            y={padT}
                            width={bandW}
                            height={innerH}
                            fill="transparent"
                            onMouseEnter={() => setActiveIndex(i)}
                            onMouseLeave={() => setActiveIndex(null)}
                        />
                    );
                })}
            </svg>

            {activeIndex !== null && (
                <div
                    className={`pointer-events-none absolute top-8 z-20 min-w-[180px] rounded-md bg-gray-700/95 px-3 py-2 text-[12px] leading-[1.8] text-white shadow-lg ${
                        xAt(activeIndex) / W > 0.6 ? "-translate-x-full" : ""
                    }`}
                    style={{ left: `calc(${(xAt(activeIndex) / W) * 100}% ${xAt(activeIndex) / W > 0.6 ? "-" : "+"} 12px)` }}
                >
                    <div className="mb-0.5 font-medium">{points[activeIndex].period}</div>
                    <div className="flex items-center justify-between gap-4">
                        <span className="text-white/70">金额</span>
                        <span>{formatExactAmount(points[activeIndex].value)}</span>
                    </div>
                </div>
            )}
        </div>
    );
};

// 整体分析 - 账期 seed（与月/天/小时序列构造使用同一套 seed 规则，保证产品维度与整体合计同源）
const overallPeriodSeed = (period: string, billType: string) => {
    const y = Number(period.slice(0, 4));
    const m = Number(period.slice(4, 6));
    if (billType === "hour") {
        const [datePart, timePart] = period.split(" ");
        const dd = Number(datePart.slice(6, 8));
        const h = Number((timePart ?? "00:00").slice(0, 2));
        return y * 8928 + m * 744 + dd * 24 + h;
    }
    if (billType === "day") {
        const dd = Number(period.slice(6, 8));
        return y * 372 + m * 31 + dd;
    }
    return y * 12 + m;
};

// 整体分析 - 账期缩放比例（天/小时账单在月基准值上均摊）
const overallPeriodScale = (billType: string) =>
    billType === "day" ? 1 / 31 : billType === "hour" ? 1 / (31 * 24) : 1;

// 整体分析 - 产品维度行（单个产品在选中账期的经营数据）
interface OverallProductRow {
    id: number;
    productName: string;            // 产品名称（已去除英文标识后缀）
    settlementUnit: string;         // 归属结算单元
    deptAttr: string;               // 结算单元的经营属性：inner / biz / 空
    totalRevenue: number;           // 总收入(元)
    productCost: number;            // 总成本(元)
    innerCost: number;              // 内部成本(元) = 总成本 - 外部成本
    outerCost: number;              // 外部成本(元) = 外部收入
    innerRevenue: number;           // 集团内收入(元)
    innerSettleRevenue: number;     // 内结收入(元)：经营属性为内结的结算单元对应的内部收入
    innerBizRevenue: number;        // 经营收入(元)：经营属性为经营的结算单元对应的内部收入
    outerRevenue: number;           // 集团外收入(元)
    innerMargin: number;            // 内结毛利率(%)
    outerMargin: number;            // 外部毛利率(%)
    profit: number;                 // 收支差额(元) = 总收入 - 总成本
}

// 整体分析 - 按账期构造产品维度数据
// 构造逻辑：各产品先在「产品分析」基准值上做稳定伪随机波动，再按整体合计值等比归一化，
// 因此「产品明细求和」严格等于顶部整体指标卡数值，也与趋势图同一账期的点位一致。
const buildOverallProductRows = (period: string, billType: string): OverallProductRow[] => {
    const seed = overallPeriodSeed(period, billType);
    const total = buildOverallRow(0, period, overallPeriodScale(billType), seed);

    const raw = productAnalysisData.map((p, idx) => {
        const rw = 0.82 + overallWave(seed + (idx + 1) * 13) * 0.38;   // 收入波动
        const cw = 0.85 + overallWave(seed + (idx + 1) * 29) * 0.34;   // 成本波动
        const attr = getUnitDeptAttr(p.settlementUnit);
        return {
            source: p,
            revenue: p.totalRevenue * rw,
            inner: p.innerRevenue * rw,
            outer: p.outerRevenue * rw,
            outerInnerPrice: p.outerInnerPriceRevenue * rw,
            innerTotal: p.innerTotalRevenue * rw,
            cost: p.productCost * cw,
            deptAttr: attr,
        };
    });

    const sumOf = (pick: (r: (typeof raw)[number]) => number) => raw.reduce((acc, r) => acc + pick(r), 0);
    const sums = {
        revenue: sumOf((r) => r.revenue),
        inner: sumOf((r) => r.inner),
        outer: sumOf((r) => r.outer),
        outerInnerPrice: sumOf((r) => r.outerInnerPrice),
        innerTotal: sumOf((r) => r.innerTotal),
        cost: sumOf((r) => r.cost),
    };
    // 等比归一化到整体合计值
    const norm = (v: number, sum: number, target: number) => (sum === 0 ? 0 : (v / sum) * target);

    return raw.map((r, idx) => {
        const innerRevenue = norm(r.inner, sums.inner, total.innerRevenue);
        const outerRevenue = norm(r.outer, sums.outer, total.outerRevenue);
        const totalRevenue = innerRevenue + outerRevenue; // 总收入 = 集团内收入 + 集团外收入
        const outerInnerPrice = norm(r.outerInnerPrice, sums.outerInnerPrice, total.outerInnerPriceRevenue);
        const innerTotalRevenue = norm(r.innerTotal, sums.innerTotal, total.innerTotalRevenue);
        const productCost = norm(r.cost, sums.cost, total.productCost);
        const outerCost = outerRevenue;             // 外部成本(元) = 外部收入
        const innerCost = productCost - outerCost;  // 内部成本(元) = 总成本 - 外部成本
        const innerProfit = innerTotalRevenue - productCost;
        const outerProfit = outerRevenue - outerInnerPrice;
        // 按结算单元经营属性拆分内结/经营收入
        const innerSettleRevenue = r.deptAttr === 'inner' ? innerRevenue : 0;
        const innerBizRevenue = r.deptAttr === 'biz' ? innerRevenue : 0;
        return {
            id: idx + 1,
            productName: cleanProductName(r.source.productName),
            settlementUnit: r.source.settlementUnit,
            deptAttr: r.deptAttr,
            totalRevenue,
            productCost,
            innerCost,
            outerCost,
            innerRevenue,
            innerSettleRevenue,
            innerBizRevenue,
            outerRevenue,
            innerMargin: innerTotalRevenue === 0 ? 0 : (innerProfit / innerTotalRevenue) * 100,
            outerMargin: outerRevenue === 0 ? 0 : (outerProfit / outerRevenue) * 100,
            profit: totalRevenue - productCost,
        };
    });
};

// 整体分析 - 产品数量概览
// 收入产品：有收入；成本产品：有内部成本或外部成本
// 盈利产品：内结毛利率 ≥ 0；亏损产品：内结毛利率 < 0
// 异常产品：外部毛利率 < 0，或只有成本没有收入
const buildOverallProductStats = (rows: OverallProductRow[]) => ({
    revenueCount: rows.filter((r) => r.totalRevenue > 0).length,
    costCount: rows.filter((r) => r.innerCost > 0 || r.outerCost > 0).length,
    profitCount: rows.filter((r) => r.innerMargin >= 0).length,
    lossCount: rows.filter((r) => r.innerMargin < 0).length,
    abnormalCount: rows.filter((r) => r.outerMargin < 0 || (r.productCost > 0 && r.totalRevenue <= 0)).length,
});

// 整体分析 - 结算单元维度聚合行
interface OverallUnitRow {
    unit: string;                   // 结算单元名称
    deptAttr: string;               // 经营属性：inner / biz / 空
    totalRevenue: number;           // 收入(元)
    innerRevenue: number;           // 内部收入(元)
    innerSettleRevenue: number;     // 内结收入(元)
    innerBizRevenue: number;        // 经营收入(元)
    outerRevenue: number;           // 外部收入(元)
    productCost: number;            // 成本(元)
    innerCost: number;              // 内部成本(元)
    outerCost: number;              // 外部成本(元)
    profit: number;                 // 收支差额(元)
    productCount: number;           // 关联产品数
}

// 整体分析 - 按结算单元聚合产品维度数据（按收入降序）
const buildOverallUnitRows = (rows: OverallProductRow[]): OverallUnitRow[] => {
    const map = new Map<string, OverallUnitRow>();
    rows.forEach((r) => {
        const cur =
            map.get(r.settlementUnit) ??
            {
                unit: r.settlementUnit,
                deptAttr: r.deptAttr,
                totalRevenue: 0,
                innerRevenue: 0,
                innerSettleRevenue: 0,
                innerBizRevenue: 0,
                outerRevenue: 0,
                productCost: 0,
                innerCost: 0,
                outerCost: 0,
                profit: 0,
                productCount: 0,
            };
        cur.totalRevenue += r.totalRevenue;
        cur.innerRevenue += r.innerRevenue;
        cur.innerSettleRevenue += r.innerSettleRevenue;
        cur.innerBizRevenue += r.innerBizRevenue;
        cur.outerRevenue += r.outerRevenue;
        cur.productCost += r.productCost;
        cur.innerCost += r.innerCost;
        cur.outerCost += r.outerCost;
        cur.productCount += 1;
        map.set(r.settlementUnit, cur);
    });
    return Array.from(map.values())
        .map((u) => ({ ...u, profit: u.totalRevenue - u.productCost }))
        .sort((a, b) => b.totalRevenue - a.totalRevenue);
};

// 整体分析 - 结算单元数量概览
const buildOverallUnitStats = (units: OverallUnitRow[]) => ({
    revenueCount: units.filter((u) => u.totalRevenue > 0).length,
    costCount: units.filter((u) => u.productCost > 0).length,
    profitCount: units.filter((u) => u.profit > 0).length,
    lossCount: units.filter((u) => u.profit < 0).length,
});

// ===== 整体分析 - 部门概览 =====
// 一个部门可关联多个结算单元，部门经营数据 = 其关联的全部结算单元收入/成本求和
interface OverallDeptConfig {
    name: string;    // 部门名称
    path: string;    // 部门在业务树中的层级路径
    units: string[]; // 关联的结算单元
}

const overallDeptConfigs: OverallDeptConfig[] = [
    { name: "应用平台部", path: "技术中台/智汇云/应用平台部", units: ["智汇云-应用平台部", "智汇云-应用平台部-视频云"] },
    { name: "云平台部", path: "技术中台/智汇云/云平台部", units: ["智汇云-云平台部-弹性计算", "智汇云-云平台部-裸金属"] },
    { name: "系统部", path: "技术中台/智汇云/系统部", units: ["智汇云-系统部-存储", "智汇云-系统部-大数据"] },
    { name: "基础架构部", path: "技术中台/智汇云/基础架构部", units: ["智汇云-基础架构部-Serverless", "智汇云-基础架构部-中间件"] },
    { name: "智能部", path: "技术中台/智汇云/智能部", units: ["智汇云-智能部"] },
];

interface OverallDeptMember {
    unit: string;          // 结算单元名称
    totalRevenue: number;  // 收入(元)
    productCost: number;   // 成本(元)
}

interface OverallDeptRow {
    name: string;
    path: string;
    members: OverallDeptMember[];
    totalRevenue: number;       // 部门收入(元) = 各结算单元收入求和
    innerRevenue: number;       // 部门内部收入(元)
    innerSettleRevenue: number; // 部门内结收入(元)
    innerBizRevenue: number;    // 部门经营收入(元)
    outerRevenue: number;       // 部门外部收入(元)
    productCost: number;        // 部门成本(元) = 各结算单元成本求和
    innerCost: number;          // 部门内部成本(元)
    outerCost: number;          // 部门外部成本(元)
    profit: number;             // 收支差额(元)
}

// 注：部门聚合在组件内基于 overallUnitRows 计算（与「结算单元概览」同源、随账期联动）

// 整体分析 - 部门数量概览
const buildOverallDeptStats = (rows: OverallDeptRow[]) => ({
    profitCount: rows.filter((d) => d.profit >= 0).length,
    lossCount: rows.filter((d) => d.profit < 0).length,
});

// 整体分析 - 结算单元柱状图通用绘制（纯 SVG 实现）
// 每个结算单元一组并排柱：主柱（深色）+ 次柱（浅色），分别代表内部/外部
const OverallUnitSplitBarChart = ({
    units,
    primary,
    secondary,
    primaryLabel,
    secondaryLabel,
    primaryColor,
    secondaryColor,
    primaryTip,
    secondaryTip,
}: {
    units: OverallUnitRow[];
    primary: (u: OverallUnitRow) => number;
    secondary: (u: OverallUnitRow) => number;
    primaryLabel: string;
    secondaryLabel: string;
    primaryColor: string;
    secondaryColor: string;
    primaryTip: string;
    secondaryTip: string;
}) => {
    const [activeIndex, setActiveIndex] = useState<number | null>(null);

    const W = 960;
    const H = 300;
    const padL = 74;
    const padR = 16;
    const padT = 16;
    const padB = 56;
    const innerW = W - padL - padR;
    const innerH = H - padT - padB;

    if (units.length === 0) {
        return <div className="flex h-[300px] items-center justify-center text-sm text-gray-400">暂无数据</div>;
    }

    // 复合（堆叠）柱：纵轴上限取「内部 + 外部」的合计
    const maxVal = Math.max(...units.map((u) => primary(u) + secondary(u)), 1);
    const step = Math.pow(10, Math.floor(Math.log10(maxVal))) / 2;
    const yMax = Math.ceil(maxVal / step) * step;
    const yTicks = Array.from({ length: 5 }, (_, i) => (yMax / 4) * i);

    const bandW = innerW / units.length;
    const barW = Math.min(36, bandW * 0.46);   // 复合柱宽（每个结算单元一根）
    const yOf = (v: number) => padT + innerH - (v / yMax) * innerH;
    const hOf = (v: number) => (v / yMax) * innerH;   // 数值 → 段高

    return (
        <div className="relative">
            <svg viewBox={`0 0 ${W} ${H}`} className="w-full" style={{ height: H }} preserveAspectRatio="none">
                {/* 横向网格线与左侧金额刻度 */}
                {yTicks.map((t, i) => (
                    <g key={i}>
                        <line x1={padL} y1={yOf(t)} x2={W - padR} y2={yOf(t)} stroke="#f1f5f9" strokeWidth={1} />
                        <text x={padL - 8} y={yOf(t) + 4} textAnchor="end" className="fill-gray-400" style={{ fontSize: 11 }}>
                            {formatWan(t)}
                        </text>
                    </g>
                ))}
                {/* X 轴 */}
                <line x1={padL} y1={padT + innerH} x2={W - padR} y2={padT + innerH} stroke="#e5e7eb" strokeWidth={1} />

                {units.map((u, idx) => {
                    const cx = padL + bandW * idx + bandW / 2;
                    const pv = primary(u);
                    const sv = secondary(u);
                    const total = pv + sv;
                    const baseY = padT + innerH;
                    const pH = hOf(pv);   // 下段（内部）高度
                    const sH = hOf(sv);   // 上段（外部）高度
                    return (
                        <g
                            key={u.unit}
                            onMouseEnter={() => setActiveIndex(idx)}
                            onMouseLeave={() => setActiveIndex(null)}
                        >
                            {/* hover 命中区 */}
                            <rect x={cx - bandW / 2} y={padT} width={bandW} height={innerH} fill={activeIndex === idx ? "#f8fafc" : "transparent"} />
                            {/* 下段：内部 */}
                            <rect x={cx - barW / 2} y={baseY - pH} width={barW} height={pH} fill={primaryColor} opacity={0.9} />
                            {/* 上段：外部（堆叠在内部之上，无间距直接紧贴）；有值时保留最小 2px 可见高度 */}
                            {sv > 0 && <rect x={cx - barW / 2} y={baseY - pH - Math.max(sH, 2)} width={barW} height={Math.max(sH, 2)} rx={2} fill={secondaryColor} opacity={0.9} />}
                            {/* 柱顶合计 */}
                            {total > 0 && (
                                <text x={cx} y={baseY - pH - sH - 6} textAnchor="middle" className="fill-gray-600" style={{ fontSize: 11 }}>
                                    {formatWan(total)}
                                </text>
                            )}
                            {/* X 轴结算单元名称（过长换行展示） */}
                            <text x={cx} y={padT + innerH + 18} textAnchor="middle" className="fill-gray-500" style={{ fontSize: 11 }}>
                                {u.unit.length > 8 ? u.unit.slice(0, 8) : u.unit}
                            </text>
                            {u.unit.length > 8 && (
                                <text x={cx} y={padT + innerH + 32} textAnchor="middle" className="fill-gray-500" style={{ fontSize: 11 }}>
                                    {u.unit.slice(8)}
                                </text>
                            )}
                        </g>
                    );
                })}
            </svg>

            {/* 图例 */}
            <div className="mt-1 flex items-center justify-center gap-5">
                <span className="inline-flex items-center gap-1.5 text-[12px] text-gray-600">
                    <span className="inline-block h-2.5 w-3.5 rounded-sm" style={{ background: primaryColor }} />{primaryLabel}
                </span>
                <span className="inline-flex items-center gap-1.5 text-[12px] text-gray-600">
                    <span className="inline-block h-2.5 w-3.5 rounded-sm" style={{ background: secondaryColor }} />{secondaryLabel}
                </span>
            </div>

            {/* hover 详情 */}
            {activeIndex !== null && units[activeIndex] && (
                <div className="pointer-events-none absolute left-1/2 top-0 -translate-x-1/2 rounded bg-gray-700 px-3 py-2 text-[12px] leading-[1.8] text-white shadow-lg">
                    <div className="font-medium">{units[activeIndex].unit}</div>
                    <div>{primaryLabel}：{formatExactAmount(primary(units[activeIndex]))}</div>
                    <div>{secondaryLabel}：{formatExactAmount(secondary(units[activeIndex]))}</div>
                    <div className="mt-0.5 border-t border-white/20 pt-0.5">
                        合计：{formatExactAmount(primary(units[activeIndex]) + secondary(units[activeIndex]))}
                    </div>
                </div>
            )}
        </div>
    );
};

// 整体分析 - 部门「收入 vs 成本」分组柱状图（与结算单元版本结构一致，数据源换为 OverallDeptRow）
const OverallDeptRevenueCostBarChart = ({ depts }: { depts: OverallDeptRow[] }) => {
    const [activeIndex, setActiveIndex] = useState<number | null>(null);

    const W = 960;
    const H = 300;
    const padL = 74;
    const padR = 16;
    const padT = 28;
    const padB = 64;
    const innerW = W - padL - padR;
    const innerH = H - padT - padB;
    const LABEL_MIN_GAP = 13;

    if (depts.length === 0) {
        return <div className="flex h-[300px] items-center justify-center text-sm text-gray-400">暂无数据</div>;
    }

    const maxVal = Math.max(
        ...depts.map((d) => d.innerRevenue + d.outerRevenue),
        ...depts.map((d) => d.innerCost + d.outerCost),
        1
    );
    const step = Math.pow(10, Math.floor(Math.log10(maxVal))) / 2;
    const yMax = Math.ceil(maxVal / step) * step;
    const yTicks = Array.from({ length: 5 }, (_, i) => (yMax / 4) * i);

    const balances = depts.map((d) => d.innerRevenue + d.outerRevenue - d.innerCost - d.outerCost);
    const maxBalance = Math.max(...balances);
    const bestIndex = maxBalance > 0 ? balances.indexOf(maxBalance) : -1;

    const bandW = innerW / depts.length;
    const groupGap = Math.min(8, bandW * 0.12);
    const barW = Math.min(24, (bandW - groupGap * 2) / 2 - 2);
    const showBarLabels = bandW >= 60;
    const yOf = (v: number) => padT + innerH - (v / yMax) * innerH;
    const hOf = (v: number) => Math.max(0, (v / yMax) * innerH);

    return (
        <div className="relative">
            {/* 图例 */}
            <div className="mb-2 flex flex-wrap items-center gap-5 px-1">
                <span className="inline-flex items-center gap-1.5 text-[12px] text-gray-600">
                    <span className="inline-block h-2.5 w-3.5 rounded-sm bg-[#3b82f6]" />内部收入
                </span>
                <span className="inline-flex items-center gap-1.5 text-[12px] text-gray-600">
                    <span className="inline-block h-2.5 w-3.5 rounded-sm bg-[#93c5fd]" />外部收入
                </span>
                <span className="inline-flex items-center gap-1.5 text-[12px] text-gray-600">
                    <span className="inline-block h-2.5 w-3.5 rounded-sm bg-[#f97316]" />内部成本
                </span>
                <span className="inline-flex items-center gap-1.5 text-[12px] text-gray-600">
                    <span className="inline-block h-2.5 w-3.5 rounded-sm bg-[#fdba74]" />外部成本
                </span>
            </div>

            <svg viewBox={`0 0 ${W} ${H}`} className="w-full" style={{ height: H }} preserveAspectRatio="none">
                {/* 横向网格线 + 左侧刻度 */}
                {yTicks.map((t, i) => (
                    <g key={i}>
                        <line x1={padL} y1={yOf(t)} x2={W - padR} y2={yOf(t)} stroke="#f1f5f9" strokeWidth={1} />
                        <text x={padL - 8} y={yOf(t) + 4} textAnchor="end" className="fill-gray-400" style={{ fontSize: 11 }}>
                            {formatWan(t)}
                        </text>
                    </g>
                ))}
                {/* X 轴 */}
                <line x1={padL} y1={padT + innerH} x2={W - padR} y2={padT + innerH} stroke="#e5e7eb" strokeWidth={1} />

                {depts.map((d, idx) => {
                    const cx = padL + bandW * idx + bandW / 2;
                    // 收入柱（左）
                    const revInner = d.innerRevenue;
                    const revOuter = d.outerRevenue;
                    const revTotal = revInner + revOuter;
                    const revIH = hOf(revInner);
                    const revOH = hOf(revOuter);
                    const revBaseY = padT + innerH;
                    const revCx = cx - barW / 2 - groupGap / 2;

                    // 成本柱（右）
                    const costInner = d.innerCost;
                    const costOuter = d.outerCost;
                    const costTotal = costInner + costOuter;
                    const costIH = hOf(costInner);
                    const costOH = hOf(costOuter);
                    const costCx = cx + barW / 2 + groupGap / 2;

                    // 柱顶数值标签防重叠
                    const revTopY = revBaseY - revIH - revOH;
                    const costTopY = revBaseY - costIH - costOH;
                    let revLabelY = revTopY - 5;
                    let costLabelY = costTopY - 5;
                    if (Math.abs(revLabelY - costLabelY) < LABEL_MIN_GAP) {
                        const topY = Math.min(revLabelY, costLabelY);
                        revLabelY = topY - LABEL_MIN_GAP;
                        costLabelY = topY;
                    }

                    return (
                        <g
                            key={d.name}
                            onMouseEnter={() => setActiveIndex(idx)}
                            onMouseLeave={() => setActiveIndex(null)}
                        >
                            {/* hover 命中区 */}
                            <rect x={cx - bandW / 2} y={padT} width={bandW} height={innerH} fill={activeIndex === idx ? "#f8fafc" : "transparent"} />

                            {/* 收入柱：下段内部，上段外部；外部段极小时保留最小 2px 可见高度 */}
                            <rect x={revCx - barW / 2} y={revBaseY - revIH} width={barW} height={revIH} fill="#3b82f6" opacity={0.9} />
                            {revOuter > 0 && <rect x={revCx - barW / 2} y={revBaseY - revIH - Math.max(revOH, 2)} width={barW} height={Math.max(revOH, 2)} rx={2} fill="#93c5fd" opacity={0.9} />}
                            {showBarLabels && revTotal > 0 && (
                                <text x={revCx} y={revLabelY} textAnchor="middle" fill="#2563eb" style={{ fontSize: 10 }}>
                                    {formatWan(revTotal)}
                                </text>
                            )}

                            {/* 成本柱：下段内部，上段外部 */}
                            <rect x={costCx - barW / 2} y={revBaseY - costIH} width={barW} height={costIH} fill="#f97316" opacity={0.9} />
                            <rect x={costCx - barW / 2} y={revBaseY - costIH - costOH} width={barW} height={costOH} rx={2} fill="#fdba74" opacity={0.9} />
                            {showBarLabels && costTotal > 0 && (
                                <text x={costCx} y={costLabelY} textAnchor="middle" fill="#ea580c" style={{ fontSize: 10 }}>
                                    {formatWan(costTotal)}
                                </text>
                            )}

                            {/* X 轴部门名称 */}
                            <text x={cx} y={padT + innerH + 16} textAnchor="middle" className="fill-gray-500" style={{ fontSize: 11 }}>
                                {d.name.length > 6 ? d.name.slice(0, 6) : d.name}
                            </text>
                            {d.name.length > 6 && (
                                <text x={cx} y={padT + innerH + 29} textAnchor="middle" className="fill-gray-500" style={{ fontSize: 11 }}>
                                    {d.name.slice(6)}
                                </text>
                            )}

                            {/* 盈亏标记 */}
                            <text
                                x={cx}
                                y={padT + innerH + (d.name.length > 6 ? 42 : 29)}
                                textAnchor="middle"
                                fill={balances[idx] >= 0 ? "#16a34a" : "#ef4444"}
                                style={{ fontSize: 10 }}
                            >
                                {balances[idx] >= 0 ? "盈利" : "亏损"}
                            </text>

                            {/* 毛利最高标注 */}
                            {idx === bestIndex && (
                                <text
                                    x={cx}
                                    y={padT + innerH + (d.name.length > 6 ? 55 : 42)}
                                    textAnchor="middle"
                                    fill="#f59e0b"
                                    style={{ fontSize: 10, fontWeight: 600 }}
                                >
                                    ★ 毛利最高
                                </text>
                            )}
                        </g>
                    );
                })}
            </svg>

            {/* hover 详情 tooltip */}
            {activeIndex !== null && depts[activeIndex] && (() => {
                const d = depts[activeIndex];
                const revTotal = d.innerRevenue + d.outerRevenue;
                const costTotal = d.innerCost + d.outerCost;
                const balance = revTotal - costTotal;
                return (
                    <div className="pointer-events-none absolute left-1/2 top-0 -translate-x-1/2 rounded bg-gray-700 px-3 py-2 text-[12px] leading-[1.8] text-white shadow-lg z-20">
                        <div className="font-medium mb-0.5">{d.name}</div>
                        <div className="border-b border-white/20 pb-1 mb-1">
                            <span className="inline-block w-2 h-2 rounded-sm bg-[#3b82f6] mr-1 align-middle" />内部收入：{formatExactAmount(d.innerRevenue)}
                        </div>
                        <div>
                            <span className="inline-block w-2 h-2 rounded-sm bg-[#93c5fd] mr-1 align-middle" />外部收入：{formatExactAmount(d.outerRevenue)}
                        </div>
                        <div className="mt-0.5 border-t border-white/20 pt-0.5">收入合计：{formatExactAmount(revTotal)}</div>
                        <div className="mt-1 border-t border-white/20 pt-1">
                            <span className="inline-block w-2 h-2 rounded-sm bg-[#f97316] mr-1 align-middle" />内部成本：{formatExactAmount(d.innerCost)}
                        </div>
                        <div>
                            <span className="inline-block w-2 h-2 rounded-sm bg-[#fdba74] mr-1 align-middle" />外部成本：{formatExactAmount(d.outerCost)}
                        </div>
                        <div className="mt-0.5 border-t border-white/20 pt-0.5">成本合计：{formatExactAmount(costTotal)}</div>
                        <div className="mt-1 border-t border-white/30 pt-1">
                            收支差：
                            <span className={balance >= 0 ? "text-green-300" : "text-red-300"}>
                                {balance < 0 ? "-" : ""}{formatExactAmount(Math.abs(balance))}
                            </span>
                        </div>
                        {d.members.length > 0 && (
                            <div className="mt-1 border-t border-white/20 pt-1 text-[11px] text-white/70">
                                关联结算单元：{d.members.map((m) => m.unit).join("、")}
                            </div>
                        )}
                    </div>
                );
            })()}
        </div>
    );
};

